const ks = [...($('Keys p1').first().json.keys||[]), ...($input.first().json.keys||[])];
const ORDER = ['courses','lessons','chapters','tests','test_thresholds'];
const ids = [];
for (const k of ks) { const n = (k.key_name||{}).web||''; const p = n.split('.')[0]; if (!ORDER.includes(p)) continue; const tg = k.tags||[]; if (tg.includes('z_human') || tg.some(t => t==='questions' || t.startsWith('test_questions'))) continue; if (/\.content$/.test(n)) continue; ids.push(k.key_id); }
ids.sort((a,b)=>a-b); const step = Math.max(1, Math.floor(ids.length/45)); const pick = ids.filter((_,i)=>i%step===0).slice(0,45);
return [{ json: { n: ids.length, ids: pick.join(',') } }];

const b = $input.first().json; if (!Array.isArray(b.keys)) throw new Error('keys missing: ' + JSON.stringify(b).slice(0,200));
const INTERNAL = new Set(['maria@efuturemedia.com','maria+devs@efuturemedia.com','kseniya.krasovskaya@efuturemedia.com','raul@efuturemedia.com','support@lokalise.com','']);
const NAMES = {da:'Danish',nl:'Dutch',et:'Estonian',fr:'French',de:'German',id:'Indonesian',it:'Italian',ko:'Korean',lv:'Latvian',lt:'Lithuanian',ms:'Malay',no:'Norwegian Bokmål',pl:'Polish',pt:'Brazilian Portuguese',ro:'Romanian',es:'European Spanish',sv:'Swedish',th:'Thai'};
const strip = s => String(s||'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim().slice(0,400);
const out = [];
for (const iso of Object.keys(NAMES)) { const pairs = [];
  for (const k of b.keys) { const tr = k.translations||[]; const en = tr.find(x=>x.language_iso==='en'); const t = tr.find(x=>x.language_iso===iso);
    if (!en || !t || typeof t.translation !== 'string' || !t.translation.trim()) continue; if (!INTERNAL.has((t.modified_by_email||'').toLowerCase())) continue;
    pairs.push({ en: strip(en.translation), t: strip(t.translation) }); }
  const list = pairs.map((p,i)=> (i+1) + '. EN: ' + p.en + '\n   ' + iso.toUpperCase() + ': ' + p.t).join('\n') || '1. EN: Hello\n   X: Hello';
  const body = { model: 'gpt-4.1', temperature: 0, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: 'You are a strict senior ' + NAMES[iso] + ' localization reviewer. Rate each translation of personality-course and personality-test UI text from 1 (unusable machine translation: wrong meaning, broken grammar) to 5 (reads as natural native copy, accurate). Return JSON {"scores":[integers in order]}.' }, { role: 'user', content: list } ] };
  out.push({ json: { iso, n: pairs.length, body: JSON.stringify(body) } }); }
return out;

const reqs = $('Build').all(); const res = $input.all(); const rows = [];
res.forEach((it,i) => { const r = reqs[i].json; let s = [];
  try { s = JSON.parse(it.json.choices[0].message.content).scores || []; } catch(e) {}
  const avg = (s.length && r.n) ? s.reduce((a,b)=>a+b,0)/s.length : null; rows.push({ iso: r.iso, n: r.n, scored: s.length, avg: avg == null ? null : Math.round(avg*100)/100, err: it.json.error ? JSON.stringify(it.json.error).slice(0,200) : null }); });
rows.sort((a,b)=>(a.avg == null ? 9 : a.avg)-(b.avg == null ? 9 : b.avg)); return [{ json: { rows } }];
